        add("Game Bar recording and screenshots stop working until you turn captures back on (Settings > Gaming > Captures).", "Aufnahmen und Screenshots über die Game Bar gehen nicht mehr, bis du sie wieder einschaltest (Einstellungen > Spielen > Aufnahmen).");
        add("Transparency effects", "Transparenz-Effekte");
